### 7.4 Component CSS - Buttons & Form Elements

Thiết kế button system hoàn chỉnh, bao gồm all states và variants.

```css
/* css/components/button.css */

/* ===== BUTTON SYSTEM ===== */
/* Button system dùng CSS custom properties composition,
   không phải utility-first thuần túy. Mỗi variant chỉ override
   những property cần thiết. */

.btn {
    /* Base styles */
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);

    /* Sizing */
    height: 2.25rem;          /* 36px - touch-friendly */
    padding: 0 var(--space-4);
    font-size: var(--text-sm);
    font-weight: var(--font-medium);
    line-height: 1;

    /* Shape & Border */
    border-radius: var(--radius-md);
    border: 1px solid transparent;
    cursor: pointer;
    white-space: nowrap;

    /* Transitions */
    transition: all var(--transition-fast);
    outline: none;

    /* Focus ring - phải visible cho accessibility */
    &:focus-visible {
        box-shadow: 0 0 0 3px var(--color-brand-200);
    }

    /* Disabled state */
    &:disabled,
    &[aria-disabled="true"] {
        opacity: 0.5;
        cursor: not-allowed;
        pointer-events: none;
    }

    /* Sizes */
    &--sm {
        height: 1.75rem;     /* 28px */
        padding: 0 var(--space-3);
        font-size: var(--text-xs);
        border-radius: var(--radius-sm);
    }

    &--lg {
        height: 2.75rem;     /* 44px */
        padding: 0 var(--space-6);
        font-size: var(--text-base);
    }

    /* Primary variant - brand color fill */
    &--primary {
        background-color: var(--color-brand-500);
        color: white;
        border-color: var(--color-brand-500);

        &:hover:not(:disabled) {
            background-color: var(--color-brand-600);
            border-color: var(--color-brand-600);
            transform: translateY(-1px);
            box-shadow: var(--shadow-md);
        }

        &:active:not(:disabled) {
            background-color: var(--color-brand-700);
            transform: translateY(0);
            box-shadow: var(--shadow-sm);
        }
    }

    /* Secondary variant - outline style */
    &--secondary {
        background-color: transparent;
        color: var(--text-primary);
        border-color: var(--border-default);

        &:hover:not(:disabled) {
            background-color: var(--bg-hover);
            border-color: var(--color-gray-400);
        }

        &:active:not(:disabled) {
            background-color: var(--bg-active);
        }
    }

    /* Ghost variant - chỉ có text, không border */
    &--ghost {
        background-color: transparent;
        color: var(--text-secondary);
        border-color: transparent;

        &:hover:not(:disabled) {
            background-color: var(--bg-hover);
            color: var(--text-primary);
        }
    }

    /* Danger variant */
    &--danger {
        background-color: var(--color-error-500);
        color: white;
        border-color: var(--color-error-500);

        &:hover:not(:disabled) {
            background-color: var(--color-error-600);
            border-color: var(--color-error-600);
        }
    }

    /* Icon button (square) */
    &--icon {
        width: 2.25rem;
        padding: 0;

        &.btn--sm { width: 1.75rem; }
        &.btn--lg { width: 2.75rem; }
    }

    /* Loading state - spinner replaces content */
    &--loading {
        position: relative;
        color: transparent !important;
        pointer-events: none;

        &::after {
            content: '';
            position: absolute;
            width: 1rem;
            height: 1rem;
            border: 2px solid currentColor;
            border-right-color: transparent;
            border-radius: 50%;
            animation: spin 0.6s linear infinite;
        }
    }
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* ===== INPUT SYSTEM ===== */
.input {
    display: block;
    width: 100%;
    height: 2.25rem;
    padding: 0 var(--space-3);
    font-size: var(--text-sm);
    color: var(--text-primary);
    background-color: var(--bg-surface);
    border: 1px solid var(--border-default);
    border-radius: var(--radius-md);
    transition: border-color var(--transition-fast), box-shadow var(--transition-fast);

    &::placeholder {
        color: var(--text-muted);
    }

    &:hover:not(:disabled):not(:focus) {
        border-color: var(--color-gray-400);
    }

    &:focus {
        outline: none;
        border-color: var(--color-brand-500);
        box-shadow: 0 0 0 3px var(--color-brand-100);
    }

    &:disabled {
        background-color: var(--bg-hover);
        cursor: not-allowed;
        opacity: 0.6;
    }

    /* Error state */
    &--error {
        border-color: var(--color-error-500);

        &:focus {
            box-shadow: 0 0 0 3px var(--color-error-100);
        }
    }

    /* With icon */
    &--with-icon {
        padding-left: 2.5rem;

        ~ .input-icon {
            left: var(--space-3);
            color: var(--text-muted);
        }
    }
}

/* Input label */
.form-label {
    display: block;
    margin-bottom: var(--space-2);
    font-size: var(--text-sm);
    font-weight: var(--font-medium);
    color: var(--text-primary);
}

.form-hint {
    margin-top: var(--space-1);
    font-size: var(--text-xs);
    color: var(--text-muted);
}

.form-error {
    margin-top: var(--space-1);
    font-size: var(--text-xs);
    color: var(--color-error-600);
    display: flex;
    align-items: center;
    gap: var(--space-1);
}
```

### 7.5 Dashboard Page - Real Data Display

Một trang dashboard thực tế hiển thị KPI cards, chart placeholder, và data table.

```cshtml
@* Areas/Admin/Pages/Dashboard/Index.cshtml *@
@page
@model IndexModel
@{
    Layout = "~/Views/Shared/_Layout.cshtml";
    ViewData["Title"] = "Dashboard";
    ViewData["Description"] = "Overview of your store performance";
}

@section Styles {
    <link rel="stylesheet" href="~/css/pages/dashboard.css" />
