    &--paid,
    &--completed,
    &--delivered {
        background-color: #d1fae5;
        color: #065f46;
    }

    /* Shipped: xanh dương nhạt - đang vận chuyển */
    &--shipped {
        background-color: #e0f2fe;
        color: #075985;
    }

    /* Cancelled: đỏ nhạt - thất bại/đã hủy */
    &--cancelled,
    &--failed,
